('charbel', 'São Charbel Makhlouf', 'O Eremita de Annaya', '24 de Julho', 7, 24, '1828', '1898', ARRAY['Pessoas doentes','Paz','Cura','Líbano']::TEXT[], 'Monge maronita libanês', 'Youssef Antoun Makhlouf nasceu numa pequena aldeia no norte do Líbano', 'mystic', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Saint_Charbel_Makhlouf.jpg/440px-Saint_Charbel_Makhlouf.jpg', 'Senhor Deus Todo-Poderoso', ARRAY['Silêncio','Oração','Penitência','Obediência']::TEXT[], ARRAY['O silêncio fala a Deus.','Quem permanece em Deus','Deus permanece nele.']::TEXT[]),
('estanislau', 'Santo Estanislau de Cracóvia', 'Bispo e Mártir', '11 de Abril', 4, 11, '1030', '1079', ARRAY['Polônia','Cracóvia','Estudantes morais']::TEXT[], 'Bispo de Cracóvia e um dos primeiros santos poloneses. Conhecido por sua coragem ao confrontar a imoralidade do Rei Boleslau II', 'Estanislau nasceu em Szczepanów e estudou em Gniezno e Paris antes de ser ordenado sacerdote. Em 1072', 'martyr', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/ca/Stanislaus_of_Szczepanow.jpg/440px-Stanislaus_of_Szczepanow.jpg', 'Ó Deus', ARRAY['Coragem','Fidelidade','Zelo Pastoral','Integridade']::TEXT[], ARRAY['Prefiro morrer a trair a lei de Deus.','O dever de um bispo é proteger seu rebanho','mesmo contra reis.']::TEXT[]),
('rita-cassia', 'Santa Rita de Cássia', 'Advogada das Causas Impossíveis', '22 de Maio', 5, 22, '1381', '1457', ARRAY['Causas impossíveis','Casamentos difíceis','Viúvas','Doentes']::TEXT[], '', 'Rita nasceu numa família humilde e', 'mystic', 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Santa_Rita_da_Cascia_-_Santuario_Roccaporena.jpg/440px-Santa_Rita_da_Cascia_-_Santuario_Roccaporena.jpg', 'Ó poderosa e gloriosa Santa Rita', ARRAY['Paciência','Perdão','Penitência','Confiança']::TEXT[], ARRAY['Não há nada impossível para Deus.','A paciência é o caminho para a paz.']::TEXT[]),
('nha-chica', 'Beata Nhá Chica', 'A Mãe dos Pobres de Baependi', '14 de Junho', 6, 14, '1808', '1895', ARRAY['Pobres','Baependi','Causas impossíveis']::TEXT[], 'Leiga mineira', 'Francisca de Paula de Jesus', 'mystic', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Nh%C3%A1_Chica.jpg/440px-Nh%C3%A1_Chica.jpg', 'Beata Nhá Chica', ARRAY['Oração','Caridade','Simplicidade','Devoção mariana']::TEXT[], ARRAY['Quem reza e trabalha não precisa de mais nada.','Confiem em Nossa Senhora','ela nunca abandona seus filhos.','A caridade é a maior de todas as virtudes.']::TEXT[]),
('maria-mae-deus', 'Santa Maria', 'Theotokos', '1 de Janeiro', 1, 1, 'Séc. I a.C.', 'Séc. I', ARRAY['Humanidade','Mães']::TEXT[], 'Mãe de Jesus Cristo', '', 'virgin', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Sassoferrato_-_Jungfrun_i_b%C3%B6n_-_Google_Art_Project.jpg/440px-Sassoferrato_-_Jungfrun_i_b%C3%B6n_-_Google_Art_Project.jpg', '', ARRAY['Obediência','Pureza','Fé']::TEXT[], ARRAY['Eis a serva do Senhor','faça-se em mim segundo a tua palavra.']::TEXT[]),
('basilio-gregorio', 'São Basílio Magno e São Gregório Nazianzeno', 'Doutores da Igreja', '2 de Janeiro', 1, 2, '329/330', '379/390', ARRAY['Monges','Educadores']::TEXT[], 'Dois dos três Padres Capadócios', '', 'doctor', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Sv_Vasilii_Velikii_%28765%29.jpg/440px-Sv_Vasilii_Velikii_%28765%29.jpg', '', ARRAY['Sabedoria','Caridade']::TEXT[], ARRAY['A Bíblia é a carta de Deus para a humanidade.']::TEXT[]),
